// Deterministic scenes for the automatic long-screenshot session.
// Everything is generated by a seeded PRNG, so the expected long image is exact and can be
// compared pixel by pixel (no tolerance, no heuristics).
//
// Scene layout (screen space, top to bottom):
//   [ header band : top px ]      fixed, identical in every frame
//   [ body        : bodyHeight ]  the scrolling document window
//   [ footer band : bottom px ]   fixed, identical in every frame
// The document lives in document space; at scroll offset o the body shows document rows
// [o, o + bodyHeight). The expected long image of a complete capture is
//   header (from the seed frame) + document rows [0, bodyHeight + lastOffset) + footer (last frame).
//
// The document rows carry glyph-like blocks so that a row fingerprint has real horizontal detail
// (a flat colour band carries none and can never be aligned).
//
// The ball is a plain filled circle that sits at a fixed SCREEN position and therefore occludes
// whatever document pixels pass under it. It is an overlay, never document content:
//   * with a scroll step larger than the ball diameter, every document row passes under the ball
//     at most once, so each row has a clean source in another frame;
//   * with a scroll step smaller than the ball diameter, the same document rows stay under the
//     ball in every frame and no clean source exists for them.
// With several regions, region r advances by offset * (r + 1) + regionSkew * r, so the regions
// move at different speeds and cannot be composed into a single translated plane.

export const WIDTH = 64;
export const BODY_HEIGHT = 240;
export const OFFSETS = [0, 16, 32, 48, 64];

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function clamp255(value) { return value < 0 ? 0 : value > 255 ? 255 : value; }

// Builds one document row: a base colour plus a few glyph-like blocks with strong local contrast.
function paintRow(data, row, width, base, rng) {
  for (let x = 0; x < width; x++) {
    const index = (row * width + x) * 4;
    data[index] = base[0]; data[index + 1] = base[1]; data[index + 2] = base[2]; data[index + 3] = 255;
  }
  const blocks = 3 + Math.floor(rng() * 4);
  for (let b = 0; b < blocks; b++) {
    const start = Math.floor(rng() * (width - 4));
    const span = 1 + Math.floor(rng() * 3);
    const delta = 90 + Math.floor(rng() * 140);
    const sign = rng() < 0.5 ? -1 : 1;
    const color = [clamp255(base[0] + sign * delta), clamp255(base[1] - sign * delta), clamp255(base[2] + sign * delta)];
    for (let x = start; x < start + span && x < width; x++) {
      const index = (row * width + x) * 4;
      data[index] = color[0]; data[index + 1] = color[1]; data[index + 2] = color[2]; data[index + 3] = 255;
    }
  }
}

export function buildDocument(rows, width, options) {
  const rng = mulberry32(options.seed);
  const data = new Uint8ClampedArray(width * rows * 4);
  if (options.periodic) {
    // The whole row repeats with the period, glyph blocks included, so the content is truly periodic.
    const period = Math.max(1, options.periodicPeriod);
    const templates = [];
    for (let i = 0; i < period; i++) {
      const row = new Uint8ClampedArray(width * 4);
      const base = [Math.floor(rng() * 256), Math.floor(rng() * 256), Math.floor(rng() * 256)];
      paintRow(row, 0, width, base, rng);
      templates.push(row);
    }
    for (let row = 0; row < rows; row++) data.set(templates[row % period], row * width * 4);
    return { data, width, height: rows };
  }
  for (let row = 0; row < rows; row++) {
    const base = [Math.floor(rng() * 256), Math.floor(rng() * 256), Math.floor(rng() * 256)];
    paintRow(data, row, width, base, rng);
  }
  return { data, width, height: rows };
}

function buildBand(rows, width, seed, base) {
  const rng = mulberry32(seed);
  const data = new Uint8ClampedArray(width * rows * 4);
  for (let row = 0; row < rows; row++) paintRow(data, row, width, base, rng);
  return { data, width, height: rows };
}

function fillCircle(data, width, height, centerX, centerY, radius, color, clipTop, clipBottom) {
  for (let y = Math.max(0, centerY - radius, clipTop); y <= Math.min(height - 1, centerY + radius, clipBottom); y++) {
    for (let x = Math.max(0, centerX - radius); x <= Math.min(width - 1, centerX + radius); x++) {
      const dx = x - centerX, dy = y - centerY;
      if (dx * dx + dy * dy > radius * radius) continue;
      const index = (y * width + x) * 4;
      data[index] = color[0]; data[index + 1] = color[1]; data[index + 2] = color[2]; data[index + 3] = 255;
    }
  }
}

export function createScene(options = {}) {
  const opts = {
    top: 0, bottom: 0, bodyHeight: BODY_HEIGHT, offsets: OFFSETS,
    ball: 'none', ballRadius: 6, ballCenterX: 20, ballCenterY: null, ballColor: [250, 40, 120],
    seed: 20261023, periodic: false, periodicPeriod: 24, regions: 1, regionSkew: 8,
    ...options
  };
  const width = WIDTH;
  const height = opts.top + opts.bodyHeight + opts.bottom;
  const lastOffset = opts.offsets[opts.offsets.length - 1];
  const maxRegionOffset = lastOffset * opts.regions + opts.regionSkew * (opts.regions - 1);
  const documentRows = opts.bodyHeight + maxRegionOffset;
  const document = buildDocument(documentRows, width, opts);
  const header = buildBand(opts.top, width, opts.seed + 11, [12, 16, 24]);
  const footer = buildBand(opts.bottom, width, opts.seed + 29, [200, 60, 20]);
  const regionWidth = opts.regions > 1 ? Math.floor(width / opts.regions) : width;
  const ballCenterY = opts.ballCenterY === null ? opts.top + Math.floor(opts.bodyHeight / 2) : opts.ballCenterY;

  const frames = [];
  for (let index = 0; index < opts.offsets.length; index++) {
    const offset = opts.offsets[index];
    const data = new Uint8ClampedArray(width * height * 4);
    if (opts.top > 0) data.set(header.data.subarray(0, opts.top * width * 4), 0);
    if (opts.bottom > 0) data.set(footer.data.subarray(0, opts.bottom * width * 4), (height - opts.bottom) * width * 4);
    for (let region = 0; region < opts.regions; region++) {
      const left = region * regionWidth;
      const span = region === opts.regions - 1 ? width - left : regionWidth;
      const regionOffset = offset * (region + 1) + opts.regionSkew * region;
      for (let row = 0; row < opts.bodyHeight; row++) {
        const documentRow = regionOffset + row;
        if (documentRow < 0 || documentRow >= documentRows) continue;
        for (let x = 0; x < span; x++) {
          const from = (documentRow * width + x) * 4;
          const to = ((opts.top + row) * width + left + x) * 4;
          data[to] = document.data[from]; data[to + 1] = document.data[from + 1];
          data[to + 2] = document.data[from + 2]; data[to + 3] = document.data[from + 3];
        }
      }
    }
    if (opts.ball !== 'none') {
      fillCircle(data, width, height, opts.ballCenterX, ballCenterY, opts.ballRadius, opts.ballColor, opts.top, opts.top + opts.bodyHeight - 1);
    }
    frames.push({ offset, hasBall: opts.ball !== 'none', image: { data, width, height } });
  }

  let expected = null;
  if (opts.regions === 1) {
    const expectedRows = opts.bodyHeight + lastOffset;
    const expectedHeight = opts.top + expectedRows + opts.bottom;
    const data = new Uint8ClampedArray(width * expectedHeight * 4);
    if (opts.top > 0) data.set(header.data.subarray(0, opts.top * width * 4), 0);
    data.set(document.data.subarray(0, expectedRows * width * 4), opts.top * width * 4);
    if (opts.bottom > 0) {
      const lastFrame = frames[frames.length - 1].image;
      for (let row = 0; row < opts.bottom; row++) {
        for (let x = 0; x < width; x++) {
          const from = ((height - opts.bottom + row) * width + x) * 4;
          const to = ((opts.top + expectedRows + row) * width + x) * 4;
          data[to] = lastFrame.data[from]; data[to + 1] = lastFrame.data[from + 1];
          data[to + 2] = lastFrame.data[from + 2]; data[to + 3] = lastFrame.data[from + 3];
        }
      }
    }
    expected = { data, width, height: expectedHeight };
  }

  return {
    width, height, top: opts.top, bottom: opts.bottom, bodyHeight: opts.bodyHeight, offsets: opts.offsets,
    frames, expected, expectedHeight: expected ? expected.height : 0, documentRows, document, options: opts,
    seedFrame: frames[0].image, lastFrame: frames[frames.length - 1].image
  };
}

// Document rows that a screen-fixed ball covers in the given frame.
export function ballCoveredRows(scene, frameIndex) {
  const frame = scene.frames[frameIndex];
  const radius = scene.options.ballRadius;
  const centerY = scene.options.ballCenterY === null
    ? scene.top + Math.floor(scene.bodyHeight / 2)
    : scene.options.ballCenterY;
  const first = centerY - radius - scene.top + frame.offset;
  const last = centerY + radius - scene.top + frame.offset;
  const rows = [];
  for (let row = Math.max(0, first); row <= last; row++) rows.push(row);
  return rows;
}

export function feedSession(session, scene, stepMs = 50) {
  let at = 0;
  for (const frame of scene.frames) {
    at += stepMs;
    session.accept(frame.image, at);
  }
  return at;
}

export function firstDifference(actual, expected) {
  if (!actual || !expected) return { reason: 'missing-image' };
  if (actual.width !== expected.width || actual.height !== expected.height) {
    return { reason: 'size', actual: [actual.width, actual.height], expected: [expected.width, expected.height] };
  }
  for (let index = 0; index < actual.data.length; index++) {
    if (actual.data[index] !== expected.data[index]) {
      const pixel = Math.floor(index / 4);
      return { reason: 'pixel', index, pixel, x: pixel % actual.width, y: Math.floor(pixel / actual.width),
        actual: Array.from(actual.data.slice(index, index + 4)), expected: Array.from(expected.data.slice(index, index + 4)) };
    }
  }
  return null;
}

export function countDifferentPixels(actual, expected) {
  if (!actual || !expected) return -1;
  if (actual.width !== expected.width || actual.height !== expected.height) return -1;
  let different = 0;
  for (let index = 0; index < actual.data.length; index += 4) {
    if (actual.data[index] !== expected.data[index] || actual.data[index + 1] !== expected.data[index + 1] ||
        actual.data[index + 2] !== expected.data[index + 2] || actual.data[index + 3] !== expected.data[index + 3]) different++;
  }
  return different;
}
